        static void LogChunkDiagnostic(const char* component, const wchar_t* fmt, ...)
        {
            if (!fmt || !*fmt)
                return;

            wchar_t buffer[4096] = {};
            va_list args;
            va_start(args, fmt);
            _vsnwprintf_s(buffer, _countof(buffer), _TRUNCATE, fmt, args);
            va_end(args);

            Log(L"%ls", buffer);
            LogShimW(LogLevel::Info, component, L"%ls", buffer);
        }

