        static void ObserveEngineFlameManager(void* manager)
        {
            if (!manager)
                return;

            if (!g_EngineFlamePrimaryManager)
            {
                g_EngineFlamePrimaryManager = manager;
                Log(L"[FLAME] Observed primary engine flame manager=0x%p\n", manager);
                return;
            }

            if (manager != g_EngineFlamePrimaryManager && !g_EngineFlameSecondaryManager)
            {
                g_EngineFlameSecondaryManager = manager;
                Log(L"[FLAME] Observed secondary engine flame manager=0x%p\n", manager);
            }
        }

        static bool WritePointerValue(uintptr_t address, void* value)
        {
            if (address == 0)
                return false;

            DWORD oldProtect = 0;
            if (!VirtualProtect(reinterpret_cast<void*>(address), sizeof(void*), PAGE_EXECUTE_READWRITE, &oldProtect))
                return false;

            *reinterpret_cast<void**>(address) = value;
            FlushInstructionCache(GetCurrentProcess(), reinterpret_cast<void*>(address), sizeof(void*));

            DWORD restoreProtect = 0;
            VirtualProtect(reinterpret_cast<void*>(address), sizeof(void*), oldProtect, &restoreProtect);
            return true;
        }

        // The coordinate-space math lives in include/weapon_convergence.h so it
        // can be exercised on the host by tests/weapon_convergence_tests.cpp
        // without dragging in Windows or the live game layout.
        using ConvergenceVec3 = WeaponConvergence::Vec3;
        using ConvergenceMatrix = WeaponConvergence::Matrix;

        // One breadcrumb per session the first time the crosshair leaves the
        // terrain, proving the stale-gPos guard is live rather than silently
        // never taken.
        static void LogPlayerConvergenceSkyStandDownOnce()
        {
            if (g_PlayerReticleConvergenceSkyStandDownLogged)
                return;
            g_PlayerReticleConvergenceSkyStandDownLogged = true;
            Log(L"[CONVERGE] player reticle convergence stood down: no object and no ground hit "
                L"(Reticle+0xA8 == 0), so gPos is stale; stock aim retained\n");
        }

        // One breadcrumb per session if the mount frame at weapon+0x28 does not
        // look like the orthonormal MAT_3D Weapon::Control writes there. That is
        // the single assumption the whole convergence solution rests on, so it
        // gets its own diagnostic rather than being folded into the generic
        // layout fault below.
        static void LogPlayerConvergenceMountFault(
            void* weapon,
            int slot,
            const ConvergenceMatrix& mountWorld)
        {
            if (g_PlayerReticleConvergenceMountFaultLogged)
                return;
            g_PlayerReticleConvergenceMountFaultLogged = true;
            Log(L"[CONVERGE] player reticle convergence rejected weapon=0x%p slot=%d: mount frame at +0x%X is not an orthonormal MAT_3D "
                L"(right=(%.3f, %.3f, %.3f) up=(%.3f, %.3f, %.3f) front=(%.3f, %.3f, %.3f) pos=(%.1f, %.1f, %.1f))\n",
                weapon,
                slot,
                static_cast<uint32_t>(kWeaponMountWorldMatrixOffset),
                static_cast<double>(mountWorld.rightX),
                static_cast<double>(mountWorld.rightY),
                static_cast<double>(mountWorld.rightZ),
                static_cast<double>(mountWorld.upX),
                static_cast<double>(mountWorld.upY),
                static_cast<double>(mountWorld.upZ),
                static_cast<double>(mountWorld.frontX),
                static_cast<double>(mountWorld.frontY),
                static_cast<double>(mountWorld.frontZ),
                mountWorld.positionX,
                mountWorld.positionY,
                mountWorld.positionZ);
        }

        // Weapon::Control caches Matrix_Inverse(M) at weapon+0x68 right after it
        // writes M at weapon+0x28. Comparing our own inverse against that cached
        // one, once per session, is a direct assertion that both offsets really
        // are the fields the decompile says they are -- if the layout ever
        // shifts, this prints a mismatch instead of the feature silently aiming
        // through a garbage frame.
        static void LogPlayerConvergenceLayoutCrossCheck(
            void* weapon,
            const ConvergenceMatrix& computedInverse)
        {
            if (g_PlayerReticleConvergenceLayoutCheckLogged)
                return;
            g_PlayerReticleConvergenceLayoutCheckLogged = true;

            const ConvergenceMatrix cached = *reinterpret_cast<const ConvergenceMatrix*>(
                reinterpret_cast<const uint8_t*>(weapon) + kWeaponMountInverseMatrixOffset);

            float worstRotation = 0.0f;
            const float* lhs = &computedInverse.rightX;
            const float* rhs = &cached.rightX;
            for (int i = 0; i < 9; ++i)
            {
                const float delta = std::fabs(lhs[i] - rhs[i]);
                if (delta > worstRotation)
                    worstRotation = delta;
            }
            const double worstPosition = (std::max)(
                (std::max)(std::fabs(computedInverse.positionX - cached.positionX),
                           std::fabs(computedInverse.positionY - cached.positionY)),
                std::fabs(computedInverse.positionZ - cached.positionZ));

            Log(L"[CONVERGE] weapon layout cross-check weapon=0x%p M@+0x%X I@+0x%X worstRotationDelta=%.6f worstPositionDelta=%.4f (%hs)\n",
                weapon,
                static_cast<uint32_t>(kWeaponMountWorldMatrixOffset),
                static_cast<uint32_t>(kWeaponMountInverseMatrixOffset),
                static_cast<double>(worstRotation),
                worstPosition,
                (worstRotation <= 0.01f && worstPosition <= 0.5)
                    ? "layout confirmed"
                    : "LAYOUT MISMATCH -- convergence offsets need re-deriving");
        }

        static void ApplyLocalPlayerReticleConvergence(void* craft)
        {
            if (!craft)
                return;

            auto carrierGetWeapon = reinterpret_cast<FnCarrierGetWeapon>(kCarrierGetWeaponAddr);
            auto refreshWeaponTransform =
                reinterpret_cast<FnRefreshWeaponTransform>(kRefreshWeaponTransformAddr);

            __try
            {
                if (*reinterpret_cast<void**>(kLocalUserObjectPtrAddr) != craft)
                    return;

                void* carrier = *reinterpret_cast<void**>(
                    reinterpret_cast<uint8_t*>(craft) + kCraftCarrierOffset);
                if (!carrier)
                    return;

                // Mirror Reticle::Simulate's precedence: an object under the
                // crosshair wins, and the terrain point is only the fallback.
                // Taking gPos unconditionally would aim at stale ground every
                // time the crosshair is over a unit -- exactly the case where
                // convergence matters most.
                ConvergenceVec3 target = {};
                const char* targetSource = "ground";
                void* selectObject =
                    *reinterpret_cast<void* const*>(kSmartReticleSelectObjectAddr);
                if (selectObject)
                {
                    float objectPosition[3] = {};
                    if (!TryGetGameObjectWorldPosition(selectObject, objectPosition))
                        return;
                    target = { objectPosition[0], objectPosition[1], objectPosition[2] };
                    targetSource = "object";
                }
                else
                {
                    // No object under the crosshair and no ground hit this
                    // frame means there is no reticle point at all -- the
                    // player is aiming at the sky. Stand down and leave the
                    // stock aim, which already points straight down the sight,
                    // instead of converging on a stale gPos.
                    if (*reinterpret_cast<const int*>(kSmartReticleGroundHitAddr) == 0)
                    {
                        LogPlayerConvergenceSkyStandDownOnce();
                        return;
                    }
                    target = *reinterpret_cast<const ConvergenceVec3*>(kSmartReticlePositionAddr);
                }

                if (!std::isfinite(target.x) || !std::isfinite(target.y) || !std::isfinite(target.z))
                    return;

                int retargeted = 0;
                int clamped = 0;
                ConvergenceVec3 lastMuzzle = {};
                float lastResidualDegrees = 0.0f;
                for (int slot = 0; slot < kConvergenceWeaponSlotCount; ++slot)
                {
                    void* weapon = carrierGetWeapon(carrier, slot);
                    if (!weapon)
                        continue;

                    void* weaponObject = *reinterpret_cast<void**>(
                        reinterpret_cast<uint8_t*>(weapon) + kWeaponObjectOffset);
                    if (!weaponObject)
                        continue;

                    // The mount frame the engine itself fires through. Reading
                    // it (rather than composing the _OBJ76 parent chain here)
                    // guarantees convergence solves the same equation the
                    // ordnance spawn evaluates, even if Weapon::Control has not
                    // refreshed M yet this frame.
                    const ConvergenceMatrix mountWorld =
                        *reinterpret_cast<const ConvergenceMatrix*>(
                            reinterpret_cast<const uint8_t*>(weapon) +
                            kWeaponMountWorldMatrixOffset);
                    if (!WeaponConvergence::IsFinite(mountWorld) ||
                        !WeaponConvergence::IsRotationOrthonormal(mountWorld))
                    {
                        LogPlayerConvergenceMountFault(weapon, slot, mountWorld);
                        continue;
                    }

                    LogPlayerConvergenceLayoutCrossCheck(
                        weapon, WeaponConvergence::Invert(mountWorld));

                    auto* transform = reinterpret_cast<ConvergenceMatrix*>(
                        reinterpret_cast<uint8_t*>(weaponObject) + kObj76TransformOffset);

                    WeaponConvergence::Solution solution = {};
                    const WeaponConvergence::SolveResult result =
                        WeaponConvergence::Solve(*transform, mountWorld, target, solution);
                    if (result == WeaponConvergence::SolveResult::ExceedsDeviationLimit)
                    {
                        ++clamped;
                        continue;
                    }
                    if (result != WeaponConvergence::SolveResult::Converged)
                        continue;

                    *transform = solution.mountLocal;
                    refreshWeaponTransform(weaponObject, transform);
                    lastResidualDegrees = solution.residualDegrees;

                    lastMuzzle = solution.muzzle;
                    ++retargeted;
                }

                // Breadcrumbs proving the feature reaches a weapon, and where it
                // is pointing it. Spaced out and capped: a single sample taken
                // on the first simulated frame says nothing useful, because the
                // sight matrix has not settled yet, but a handful spread across
                // the first minute of play shows whether the reticle point
                // tracks the craft or runs off the map.
                if (retargeted > 0 &&
                    g_PlayerReticleConvergenceLogCount < kPlayerReticleConvergenceLogLimit)
                {
                    const ULONGLONG now = GetTickCount64();
                    if (g_PlayerReticleConvergenceLastLogTick == 0 ||
                        now - g_PlayerReticleConvergenceLastLogTick >=
                            kPlayerReticleConvergenceLogIntervalMs)
                    {
                        g_PlayerReticleConvergenceLastLogTick = now;
                        ++g_PlayerReticleConvergenceLogCount;
                        const float dx = target.x - lastMuzzle.x;
                        const float dy = target.y - lastMuzzle.y;
                        const float dz = target.z - lastMuzzle.z;
                        Log(L"[CONVERGE] player reticle convergence applied to %d hardpoint(s) (clamped=%d) source=%hs muzzle=(%.1f, %.1f, %.1f) target=(%.1f, %.1f, %.1f) distance=%.1f residualError=%.3fdeg\n",
                            retargeted,
                            clamped,
                            targetSource,
                            static_cast<double>(lastMuzzle.x),
                            static_cast<double>(lastMuzzle.y),
                            static_cast<double>(lastMuzzle.z),
                            static_cast<double>(target.x),
                            static_cast<double>(target.y),
                            static_cast<double>(target.z),
                            static_cast<double>(std::sqrt(dx * dx + dy * dy + dz * dz)),
                            static_cast<double>(lastResidualDegrees));
                    }
                }
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                // Fail soft if a future build changes the carrier/weapon layout,
                // but leave one breadcrumb instead of silently disabling the
                // player-only feature forever.
                if (!g_PlayerReticleConvergenceLayoutFaultLogged)
                {
                    Log(L"[CONVERGE] player reticle convergence faulted while reading craft/carrier/weapon layout (craft=0x%p carrierOffset=0x%X)\n",
                        craft,
                        static_cast<uint32_t>(kCraftCarrierOffset));
                    g_PlayerReticleConvergenceLayoutFaultLogged = true;
                }
            }
        }

        static void __fastcall HovercraftUpdateWeaponAimForReticle(
            void* craft,
            void* /*edx*/,
            float dt)
        {
            reinterpret_cast<FnUpdateWeaponAim>(kHovercraftUpdateWeaponAimAddr)(craft, dt);
            if (g_PlayerReticleShotConvergenceEnabled && ReadLocalPlayerNetIdValue() == 0)
                ApplyLocalPlayerReticleConvergence(craft);
        }

        static void __fastcall WingmanUpdateWeaponAimWithConvergence(
            void* craft,
            void* /*edx*/,
            float dt)
        {
            const bool singlePlayer = ReadLocalPlayerNetIdValue() == 0;
            const uintptr_t target =
                (g_ShotConvergenceEnabled && singlePlayer)
                    ? kWalkerUpdateWeaponAimAddr
                    : kWingmanWeaponAimStockAddr;
            reinterpret_cast<FnUpdateWeaponAim>(target)(craft, dt);

            // Normal player vehicles dispatch through Wingman's override rather
            // than the Hovercraft base slot. Apply smart-reticle convergence
            // here after the stock/walker aim update so the local reticle wins.
            if (g_PlayerReticleShotConvergenceEnabled && singlePlayer)
                ApplyLocalPlayerReticleConvergence(craft);
        }

        static bool TryReadPointerValue(uintptr_t address, void*& outValue)
        {
            outValue = nullptr;
            __try
            {
                outValue = *reinterpret_cast<void**>(address);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool RefreshConvergenceVtableSlot(
            uintptr_t slotAddress,
            uintptr_t stockAddress,
            void* enabledValue,
            bool wantEnabled,
            bool& activeState,
            const wchar_t* label)
        {
            void* current = nullptr;
            if (!TryReadPointerValue(slotAddress, current))
            {
                activeState = false;
                return false;
            }

            void* stockValue = reinterpret_cast<void*>(stockAddress);
            void* desiredValue = wantEnabled ? enabledValue : stockValue;
            if (current == desiredValue)
            {
                activeState = wantEnabled;
                return true;
            }

            if (current != stockValue && current != enabledValue)
            {
                static std::unordered_set<uintptr_t> loggedSlots;
                if (loggedSlots.insert(slotAddress).second)
                {
                    Log(L"[CONVERGE] %ls vtable ownership mismatch slot=0x%08X current=0x%08X; left untouched\n",
                        label,
                        static_cast<uint32_t>(slotAddress),
                        static_cast<uint32_t>(reinterpret_cast<uintptr_t>(current)));
                }
                activeState = false;
                return false;
            }

            if (!WritePointerValue(slotAddress, desiredValue))
            {
                activeState = false;
                return false;
            }

            activeState = wantEnabled;
            Log(L"[CONVERGE] %ls %ls slot=0x%08X target=0x%08X\n",
                label,
                wantEnabled ? L"enabled" : L"disabled",
                static_cast<uint32_t>(slotAddress),
                static_cast<uint32_t>(reinterpret_cast<uintptr_t>(desiredValue)));
            return true;
        }

        static void RefreshShotConvergencePatchState()
        {
            const bool singlePlayer = ReadLocalPlayerNetIdValue() == 0;
            const bool wantWingmanWrapper =
                singlePlayer &&
                (g_ShotConvergenceEnabled || g_PlayerReticleShotConvergenceEnabled);

            RefreshConvergenceVtableSlot(
                kWingmanWeaponAimVtableSlotAddr,
                kWingmanWeaponAimStockAddr,
                reinterpret_cast<void*>(WingmanUpdateWeaponAimWithConvergence),
                wantWingmanWrapper,
                g_WingmanWeaponAimWrapperActive,
                L"wingman convergence dispatcher");
            RefreshConvergenceVtableSlot(
                kHovercraftWeaponAimVtableSlotAddr,
                kHovercraftUpdateWeaponAimAddr,
                reinterpret_cast<void*>(HovercraftUpdateWeaponAimForReticle),
                g_PlayerReticleShotConvergenceEnabled && singlePlayer,
                g_PlayerReticleHovercraftPatchActive,
                L"player smart-reticle convergence (hovercraft fallback)");

            // Feature state is reported independently even though the Wingman
            // dispatcher is shared. For normal player craft, the Wingman slot
            // is the required dispatch path; the Hovercraft hook only extends
            // coverage to direct base-derived craft.
            g_ShotConvergencePatchActive =
                g_ShotConvergenceEnabled &&
                singlePlayer &&
                g_WingmanWeaponAimWrapperActive;
            g_PlayerReticleShotConvergencePatchActive =
                g_PlayerReticleShotConvergenceEnabled &&
                singlePlayer &&
                g_WingmanWeaponAimWrapperActive;
        }

        static float ClampSmartReticleRange(float range)
        {
            return (std::clamp)(range, kSmartReticleRangeMin, kSmartReticleRangeMax);
        }

        // Builds the full stock instruction (opcode + the pooled literal's
        // address as the disp32) so the guard anchors on the instruction rather
        // than on the operand alone.
        static void BuildSmartReticleRangeSiteBytes(
            const SmartReticleRangeSite& site,
            uint8_t (&outBytes)[8])
        {
            const uint32_t pooled = static_cast<uint32_t>(kSmartReticleRangePooledLiteralAddr);
            std::memcpy(outBytes, site.opcode, site.opcodeLen);
            std::memcpy(outBytes + site.opcodeLen, &pooled, sizeof(pooled));
        }

        // Points all five reticle range loads at our own cell. Either every
        // site moves or none does -- a partial redirect would leave the reticle
        // taking its range from two different places.
        static bool EnsureSmartReticleRangeRedirect()
        {
            if (g_SmartReticleRangeRedirectActive)
                return true;

            for (const auto& site : kSmartReticleRangeSites)
            {
                uint8_t expected[8] = {};
                BuildSmartReticleRangeSiteBytes(site, expected);
                if (ExpectedBytesMatchAt(site.instructionAddr, expected, site.opcodeLen + 4u))
                    continue;

                if (!g_SmartReticleRangeRedirectFaultLogged)
                {
                    Log(L"[RETICLE] Smart-reticle range redirect stood down: site 0x%08X does not hold the stock load; leaving the shared 200.0 literal alone\n",
                        static_cast<uint32_t>(site.instructionAddr));
                    g_SmartReticleRangeRedirectFaultLogged = true;
                }
                return false;
            }

            const uint32_t cellAddr =
                static_cast<uint32_t>(reinterpret_cast<uintptr_t>(&g_SmartReticleRangeCell));
            size_t written = 0;
            for (const auto& site : kSmartReticleRangeSites)
            {
                if (!WritePatchBytes(
                        site.instructionAddr + site.opcodeLen,
                        reinterpret_cast<const uint8_t*>(&cellAddr),
                        sizeof(cellAddr)))
                {
                    break;
                }
                ++written;
            }

            if (written != std::size(kSmartReticleRangeSites))
            {
                // Put back whatever landed so the reticle stays wholly stock.
                for (size_t index = 0; index < written; ++index)
                {
                    const auto& site = kSmartReticleRangeSites[index];
                    const uint32_t pooled =
                        static_cast<uint32_t>(kSmartReticleRangePooledLiteralAddr);
                    WritePatchBytes(
                        site.instructionAddr + site.opcodeLen,
                        reinterpret_cast<const uint8_t*>(&pooled),
                        sizeof(pooled));
                }
                if (!g_SmartReticleRangeRedirectFaultLogged)
                {
                    Log(L"[RETICLE] Smart-reticle range redirect failed to write (%zu of %zu sites); rolled back\n",
                        written,
                        std::size(kSmartReticleRangeSites));
                    g_SmartReticleRangeRedirectFaultLogged = true;
                }
                return false;
            }

            g_SmartReticleRangeRedirectActive = true;
            Log(L"[RETICLE] Smart-reticle range redirected to 0x%08X across %zu site(s); shared 200.0 literal at 0x%08X left untouched\n",
                cellAddr,
                std::size(kSmartReticleRangeSites),
                static_cast<uint32_t>(kSmartReticleRangePooledLiteralAddr));
            return true;
        }

        static bool TryReadSmartReticleRange(float& outRange)
        {
            if (!g_SmartReticleRangeRedirectActive)
                return false;
            outRange = g_SmartReticleRangeCell;
            return std::isfinite(outRange);
        }

        static void RefreshSmartReticleRangeState()
        {
            const float desired = ReadLocalPlayerNetIdValue() == 0
                ? g_SmartReticleRange
                : kSmartReticleRangeStock;

            // Without the redirect the only place left to put the value is the
            // shared literal, which is what this feature must not touch. Stand
            // down and leave the reticle at its stock range.
            if (!EnsureSmartReticleRangeRedirect())
                return;

            if (g_SmartReticleRangeCell == desired)
                return;

            g_SmartReticleRangeCell = desired;
            Log(L"[RETICLE] Smart-reticle range=%.3f (%hs)\n",
                static_cast<double>(desired),
                desired == kSmartReticleRangeStock ? "stock/network" : "single-player");
        }

        static bool TryCaptureScrapPilotHudBaseline()
        {
            std::array<int, 8> captured = {};
            bool anyNonZero = false;
            __try
            {
                size_t index = 0;
                for (const auto& point : kScrapPilotHudTextPointAddresses)
                {
                    const int x = *reinterpret_cast<const int*>(point[0]);
                    const int y = *reinterpret_cast<const int*>(point[1]);
                    if (x < -4096 || x > 16384 || y < -4096 || y > 16384)
                        return false;
                    captured[index++] = x;
                    captured[index++] = y;
                    anyNonZero = anyNonZero || x != 0 || y != 0;
                }
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }

            if (!anyNonZero)
                return false;
            g_ScrapPilotHudBaseline = captured;
            g_ScrapPilotHudBaselineCaptured = true;
            return true;
        }

        static std::array<int, 8> BuildScrapPilotHudIniLayout()
        {
            std::array<int, 8> desired = g_ScrapPilotHudBaseline;
            if (!g_ScrapPilotHudLegacyLayoutEnabled)
                return desired;

            int left = desired[0];
            int top = desired[1];
            for (size_t index = 2; index + 1 < desired.size(); index += 2)
            {
                left = (std::min)(left, desired[index]);
                top = (std::min)(top, desired[index + 1]);
            }
            const int offsetX = kLegacyScrapPilotHudLeft - left;
            const int offsetY = kLegacyScrapPilotHudTop - top;
            for (size_t index = 0; index + 1 < desired.size(); index += 2)
            {
                desired[index] += offsetX;
                desired[index + 1] += offsetY;
            }
            return desired;
        }

        static bool TryWriteScrapPilotHudLayout(const std::array<int, 8>& desired)
        {
            __try
            {
                size_t index = 0;
                for (const auto& point : kScrapPilotHudTextPointAddresses)
                {
                    *reinterpret_cast<int*>(point[0]) = desired[index++];
                    *reinterpret_cast<int*>(point[1]) = desired[index++];
                }
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static void GetScrapPilotHudGroupTopLeft(
            const std::array<int, 8>& layout,
            size_t firstPoint,
            int& outLeft,
            int& outTop)
        {
            const size_t first = firstPoint * 2;
            outLeft = layout[first];
            outTop = layout[first + 1];
            const size_t second = first + 2;
            outLeft = (std::min)(outLeft, layout[second]);
            outTop = (std::min)(outTop, layout[second + 1]);
        }

        static void RefreshScrapPilotHudLayout()
        {
            const ULONGLONG now = GetTickCount64();
            if (g_ScrapPilotHudLastRefreshTick != 0 &&
                now - g_ScrapPilotHudLastRefreshTick < kScrapPilotHudRefreshMs)
            {
                return;
            }
            g_ScrapPilotHudLastRefreshTick = now;

            if (!g_ScrapPilotHudBaselineCaptured && !TryCaptureScrapPilotHudBaseline())
                return;

            const std::array<int, 8> desired = g_ScrapPilotHudMissionOverrideActive
                ? g_ScrapPilotHudMissionOverride
                : BuildScrapPilotHudIniLayout();
            if (!TryWriteScrapPilotHudLayout(desired))
                return;

            const bool panelsVisible = g_ScrapPilotHudPanelOverrideActive
                ? g_ScrapPilotHudPanelOverrideVisible
                : !g_ScrapPilotHudLegacyLayoutEnabled;
            SetStockScrapPilotPanelsVisible(panelsVisible);
        }

        static void RefreshTurretAimPitchState()
        {
            const bool active = g_TurretAimPitchEnabled && ReadLocalPlayerNetIdValue() == 0;
            g_TurretAimPitchMultiplier = active ? g_TurretAimPitchMultiplierEnhanced : 0.5f;
        }

        static void RefreshAiWeaponMaskSelectionState()
        {
            g_AiWeaponMaskSelectionActive =
                g_AiWeaponMaskSelectionEnabled && ReadLocalPlayerNetIdValue() == 0;
        }

        static void RevertAiWeaponMaskSelectionToBaseline()
        {
            g_AiWeaponMaskSelectionEnabled = kAiWeaponMaskSelectionEnabledDefault;
            g_AiWeaponMaskSelectionActive = false;
        }

